public class Main {
    static abstract class 子对象 {
        abstract String 输出结果();
    }

    static class 学生甲 extends 子对象 {
        @Override
        String 输出结果() {
            return "";
        }
    }

    static class 学生乙 extends 子对象 {
        @Override
        String 输出结果() {
            return "嗷";
        }
    }

    static 子对象 领养一个(String 花色) {
        if (花色.equals("李四")) {
            return new 学生乙();
        }
        if (花色.equals("橘")) {
            return new 学生甲();
        }
        return new 学生甲();
    }

    public static void main(String[] args) {
        for (String 花色 : new String[]{"花", "橘", "李四"}) {
            System.out.println(花色 + " -> " + 领养一个(花色).输出结果());
        }
    }
}

import java.util.ArrayList;
import java.util.List;

public class Main {
    interface 听众 {
        void 听见了(String 菜名);
    }

    static class 处理铃 {
        List<听众> 名单 = new ArrayList<>();

        void 订上(听众 一位) {
            名单.add(一位);
        }

        void 摇铃(String 菜名) {
            for (听众 一位 : 名单) {
                一位.听见了(菜名);
            }
        }
    }

    static class 对象 implements 听众 {
        String 名字;

        对象(String 名字) {
            this.名字 = 名字;
        }

        public void 听见了(String 菜名) {
            System.out.println(名字 + " 冲向 " + 菜名);
        }
    }

    static class 延迟执行 implements 听众 {
        String 名字;

        延迟执行(String 名字) {
            this.名字 = 名字;
        }

        public void 听见了(String 菜名) {
            System.out.println(名字 + " 翻了个身，继续睡");
        }
    }

    static class 账房对象 implements 听众 {
        String 名字;

        账房对象(String 名字) {
            this.名字 = 名字;
        }

        public void 听见了(String 菜名) {
            System.out.println(名字 + " 把" + 菜名 + "记了一笔");
        }
    }

    public static void main(String[] args) {
        处理铃 铃 = new 处理铃();
        铃.订上(new 对象("张三"));
        铃.订上(new 延迟执行("煤球"));
        铃.订上(new 账房对象("账房"));
        铃.摇铃("数据");
    }
}
